import{_ as t,o as e,c as l,a as n}from"./app.83c7065c.js";const x=JSON.parse('{"title":"IEEE-754标准与JS中的number类型","description":"","frontmatter":{"date":"2018-10-01","title":"IEEE-754标准与JS中的number类型"},"headers":[],"relativePath":"2018/ieee-754-and-js-number-type.md","lastUpdated":1786184870000}'),r={name:"2018/ieee-754-and-js-number-type.md"},s=n(`<ul><li><a href="#title-ieee-754%E6%A0%87%E5%87%86%E4%B8%8Ejs%E4%B8%AD%E7%9A%84number%E7%B1%BB%E5%9E%8B">title: &#39;IEEE-754标准与JS中的number类型&#39;</a></li><li><a href="#%E5%BC%95%E5%AD%90-010203-">引子: 0.1+0.2===0.3 ?</a></li><li><a href="#number%E7%B1%BB%E5%9E%8B%E7%9A%84%E4%BA%8C%E8%BF%9B%E5%88%B6%E8%A1%A8%E7%A4%BA">Number类型的二进制表示</a><ul><li><a href="#%E4%BA%8C%E8%BF%9B%E5%88%B6%E5%B0%8F%E6%95%B0%E4%B8%8E%E4%BA%8C%E8%BF%9B%E5%88%B6%E7%A7%91%E5%AD%A6%E8%AE%B0%E6%95%B0%E6%B3%95">二进制小数与二进制科学记数法</a></li></ul></li><li><a href="#ieee-754%E5%8F%8C%E7%B2%BE%E5%BA%A6%E6%B5%AE%E7%82%B9%E6%95%B0">IEEE-754双精度浮点数</a><ul><li><a href="#%E5%AD%98%E5%82%A8%E7%BB%93%E6%9E%84">存储结构</a></li><li><a href="#%E8%AE%A1%E7%AE%97%E6%96%B9%E6%B3%95">计算方法</a></li><li><a href="#%E7%89%B9%E6%AE%8A%E6%83%85%E5%86%B5">特殊情况</a></li></ul></li><li><a href="#%E6%B5%AE%E7%82%B9%E6%95%B0%E7%9A%84%E8%AF%AF%E5%B7%AE">浮点数的误差</a><ul><li><a href="#%E5%8D%81%E8%BF%9B%E5%88%B6%E8%BD%AC%E6%B5%AE%E7%82%B9%E6%95%B0">十进制转浮点数</a></li><li><a href="#%E8%88%8D%E5%85%A5">舍入</a></li></ul></li><li><a href="#0102">0.1+0.2</a></li><li><a href="#%E5%8F%82%E8%80%83%E6%96%87%E7%8C%AE">参考文献</a></li></ul><hr><h2 id="引子-0-1-0-2-0-3" tabindex="-1">引子: 0.1+0.2===0.3 ? <a class="header-anchor" href="#引子-0-1-0-2-0-3" aria-hidden="true">#</a></h2><p>用一道有点无聊的面试题作为开篇：</p><blockquote><p>0.1+0.2==0.3的结果是什么？<br> 当然是false</p></blockquote><p>为什么？简言之，因为JS的number类型是双精度浮点数，浮点数计算有误差。</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">console</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">log</span><span style="color:#A6ACCD;">(</span><span style="color:#F78C6C;">0.1</span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;">0.2</span><span style="color:#89DDFF;">==</span><span style="color:#F78C6C;">0.3</span><span style="color:#A6ACCD;">) </span><span style="color:#676E95;font-style:italic;">// false</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//控制台输入，结果如下</span></span>
<span class="line"><span style="color:#F78C6C;">0.1</span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;">0.2</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">//0.30000000000000004</span></span>
<span class="line"></span></code></pre></div><p>至于具体原因就是本文的主题了，下文会依据浮点数的原理解释上述现象。 <br><br><br></p><h2 id="number类型的二进制表示" tabindex="-1">Number类型的二进制表示 <a class="header-anchor" href="#number类型的二进制表示" aria-hidden="true">#</a></h2><p>跟其他强类型语言不同（比如C++,C#,Java等），作为动态语言的JS没有Int这样的整数类型。所有的数字，不管小数还是整数，只有一种类型：number。JS中的number类型是双精度浮点数，即用64位二进制数按照一定规则来存储及表示数字。浮点数的通行标准是IEEE-754，基本思想是使用科学记数法，利用$\\pm f \\times 2^n$这样的形式来表示数字。 <br><br></p><h3 id="二进制小数与二进制科学记数法" tabindex="-1">二进制小数与二进制科学记数法 <a class="header-anchor" href="#二进制小数与二进制科学记数法" aria-hidden="true">#</a></h3><p>十进制的小数和科学记数法很好理解，但是二进制没那么直观。我们先看个简单的例子。<br><br><strong>例1 用二进制小数和科学记数法表示32.125</strong></p><p>对于十进制来说$\\ 32.125=30+2+0.1+0.02+0.005$， 可以拆分为以下几个部分</p><table><thead><tr><th style="text-align:center;">10<sup>1</sup></th><th style="text-align:center;">10<sup>0</sup></th><th style="text-align:center;">.</th><th style="text-align:center;">10<sup>-1</sup></th><th style="text-align:center;">10<sup>-2</sup></th><th style="text-align:center;">10<sup>-3</sup></th></tr></thead><tbody><tr><td style="text-align:center;">3</td><td style="text-align:center;">2</td><td style="text-align:center;">.</td><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">5</td></tr></tbody></table><p>所以$\\ 32.125=3 \\times 10^1+2 \\times 10^0+1 \\times 10^{-1}+2 \\times 10^{-2}+5 \\times 10^{-3}=3.2125 \\times 10^{1}$</p><p>类似的，对于二进制来说，$32.125=32+0.125$，可以拆分如下</p><table><thead><tr><th style="text-align:center;">2<sup>5</sup></th><th style="text-align:center;">2<sup>4</sup></th><th style="text-align:center;">2<sup>3</sup></th><th style="text-align:center;">2<sup>2</sup></th><th style="text-align:center;">2<sup>1</sup></th><th style="text-align:center;">2<sup>0</sup></th><th style="text-align:center;">.</th><th style="text-align:center;">2<sup>-1</sup></th><th style="text-align:center;">2<sup>-2</sup></th><th style="text-align:center;">2<sup>-3</sup></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">.</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td></tr></tbody></table><p>因此$\\ 32.125=1 \\times 2^{5}+0 \\times 2^{4}+0 \\times 2^{3}+0 \\times 2^{2}+0 \\times 2^{1}+0 \\times 2^{0}+0 \\times 2^{-1}+0 \\times 2^{-2}+1 \\times 2^{-3}=100000.001_{2}=1.00000001_{2} \\times 2^{5}$</p><p>先记住这样的形式，接下来浮点数内容中会用到。<br><br><br></p><h2 id="ieee-754双精度浮点数" tabindex="-1">IEEE-754双精度浮点数 <a class="header-anchor" href="#ieee-754双精度浮点数" aria-hidden="true">#</a></h2><p>IEEE-754标准用64位二进制数，以二进制科学记数法的形式表示双精度浮点数，主要分为符号、指数、有效数字三部分。根据标准，64位浮点数的存储结构如下： <br></p><h3 id="存储结构" tabindex="-1">存储结构 <a class="header-anchor" href="#存储结构" aria-hidden="true">#</a></h3><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">63bit<br>(1 bit)</td><td style="text-align:center;">62bit...52bit<br>(11 bits)</td><td style="text-align:center;">51bit...0bit<br>(52 bits)</td></tr><tr><td style="text-align:center;">0=&gt;正数<br>1=&gt;负数</td><td style="text-align:center;">按照11bits无符号数处理<br>实际值=exponent-1023</td><td style="text-align:center;">XXXXX视为二进制小数0.XXXXX<sub>2</sub><br>实际值=fraction+1</td></tr></tbody></table><p>基本计算公式是 $\\ N = (-1)^{sign} \\times 2^{exponent-1023} \\times (1+fraction)$</p><br><h3 id="计算方法" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法" aria-hidden="true">#</a></h3><ol><li>符号位 <ul><li>sign=0的时候为正数，sign=1的时候为负数，因此定义最终的符号计算方式为$\\ (-1)^{sign}$</li></ul></li><li>指数部分 <ul><li>11位二进制数以无符号数处理，可以表示总共2<sup>11</sup>，即2048个数，可表示区间为[0, 2047]</li><li>通过减去1023的偏移量，转换到区间[-1022,1023]，原区间0和2047作为特殊情况保留</li></ul></li><li>有效数部分 <ul><li>按照标准规范之后，所有的数都默认第一位为1，因此存储时予以省略，仅存储小数点后的二进制部分</li></ul></li></ol><br><p><strong>例2 写出32.125对应的IEEE浮点数</strong><br> 例1中得到了 $32.125=1.00000001_2 \\times 2^{5}$</p><p>下面根据浮点数的计算公式，计算对应的二进制表示</p><ul><li><p>符号位：32.125显然为正数，因此符号位是0</p></li><li><p>指数部分：指数为5，根据公式，$exponent = 5+1023=1028=1024+4$，因此指数部分11位二进制数为<code>100 0000 0100</code>，如下：</p><table><thead><tr><th style="text-align:center;">10bit</th><th style="text-align:center;">9bit</th><th style="text-align:center;">8bit</th><th style="text-align:center;">7bit</th><th style="text-align:center;">6bit</th><th style="text-align:center;">5bit</th><th style="text-align:center;">4bit</th><th style="text-align:center;">3bit</th><th style="text-align:center;">2bit</th><th style="text-align:center;">1bit</th><th style="text-align:center;">0bit</th></tr></thead><tbody><tr><td style="text-align:center;">2<sup>10</sup>=1024</td><td style="text-align:center;">2<sup>9</sup>=512</td><td style="text-align:center;">2<sup>8</sup>=256</td><td style="text-align:center;">2<sup>7</sup>=128</td><td style="text-align:center;">2<sup>6</sup>=64</td><td style="text-align:center;">2<sup>5</sup>=32</td><td style="text-align:center;">2<sup>4</sup>=16</td><td style="text-align:center;">2<sup>3</sup>=8</td><td style="text-align:center;">2<sup>2</sup>=4</td><td style="text-align:center;">2<sup>1</sup>=2</td><td style="text-align:center;">2<sup>0</sup>=1</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td></tr></tbody></table></li><li><p>小数部分：因为标准只存储小数部分，因此$\\ fraction=1.00000001-1=0.00000001_2$，如下：</p></li></ul><table><thead><tr><th style="text-align:center;">51bit</th><th style="text-align:center;">50bit</th><th style="text-align:center;">49bit</th><th style="text-align:center;">48bit</th><th style="text-align:center;">47bit</th><th style="text-align:center;">46bit</th><th style="text-align:center;">45bit</th><th style="text-align:center;">44bit</th><th style="text-align:center;">43bit</th><th style="text-align:center;">42bit</th><th style="text-align:center;">...</th><th style="text-align:center;">0bit</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">...</td><td style="text-align:center;">0</td></tr></tbody></table><p>最终的二进制表示为</p><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">10000000100</td><td style="text-align:center;">(1).0000000100000000000000000000000000000000000000000000</td></tr></tbody></table><br><h3 id="特殊情况" tabindex="-1">特殊情况 <a class="header-anchor" href="#特殊情况" aria-hidden="true">#</a></h3><p>特殊情况有3种，分别是0，正负无穷大和NaN：</p><ul><li>0 <ul><li>符号位为0</li><li>指数部分全为0，即exponent为0</li><li>小数部分为0</li></ul></li><li>无穷大 <ul><li>符号位任意</li><li>指数部分全为1，即exponent为2047</li><li>小数部分为0</li></ul></li><li>NaN <ul><li>符号位任意</li><li>指数部分全为1，即exponent为2047</li><li>小数部分非0</li></ul></li></ul><p><br><br></p><h2 id="浮点数的误差" tabindex="-1">浮点数的误差 <a class="header-anchor" href="#浮点数的误差" aria-hidden="true">#</a></h2><p>双精度浮点数只有64位，如果一个十进制数无法被64位二进制数完整表示，那么就会产生误差。首先十进制数需要转换为二进制数，再将二进制数转换为符合IEEE-754标准的形式。这个过程有可能带来误差。<br><br></p><h3 id="十进制转浮点数" tabindex="-1">十进制转浮点数 <a class="header-anchor" href="#十进制转浮点数" aria-hidden="true">#</a></h3><p>十进制转换时，按照整数部分+小数部分分别计算的原则。整数部分使用除2取余法，小数部分使用乘2取整法。<br><br></p><p><strong>例3 32.125转换为二进制数</strong><br> 先处理整数部分32</p><table><thead><tr><th style="text-align:center;">被除数</th><th style="text-align:center;">商</th><th style="text-align:center;">余数</th></tr></thead><tbody><tr><td style="text-align:center;">32</td><td style="text-align:center;">16</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">16</td><td style="text-align:center;">8</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">4</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">2</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">1</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">0</td><td style="text-align:center;">1</td></tr></tbody></table><p><strong>从下往上取余数，于是得到<code>10 0000</code></strong></p><p>再处理小数部分</p><table><thead><tr><th style="text-align:center;">被乘数</th><th style="text-align:center;">积</th><th style="text-align:center;">整数</th></tr></thead><tbody><tr><td style="text-align:center;">0.125</td><td style="text-align:center;">0.25</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.25</td><td style="text-align:center;">0.5</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.5</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td></tr></tbody></table><p><strong>从上往下取整数，得到<code>001</code></strong></p><p>所以最后得到$\\ 32.125=100000.001_2$。<br><br><strong>例4 将0.1转换为IEEE浮点数</strong><br> 按照例3中的小数转换为二进制的方法，计算如下：</p><table><thead><tr><th style="text-align:center;">被乘数</th><th style="text-align:center;">积</th><th style="text-align:center;">整数</th></tr></thead><tbody><tr><td style="text-align:center;">0.1</td><td style="text-align:center;">0.2</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.2</td><td style="text-align:center;">0.4</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.4</td><td style="text-align:center;">0.8</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.8</td><td style="text-align:center;">1.6</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.6</td><td style="text-align:center;">1.2</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.2</td><td style="text-align:center;">0.4</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.4</td><td style="text-align:center;">0.8</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.8</td><td style="text-align:center;">1.6</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.6</td><td style="text-align:center;">1.2</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.2</td><td style="text-align:center;">0.4</td><td style="text-align:center;">0</td></tr></tbody></table><p>可以看到出现了循环，$\\ 0.1_{10} = 0.0\\overline{0011}_2=1.1 \\overline{0011}_2 \\times 2^{-4}$</p><p>无限循环的0.1无法被有限64位完整表示，必须截断后才能保存，这个过程必然会带来误差。先按照例2的方法，可将其转换为浮点数，如下：</p><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th><th style="text-align:center;">无法表示部分</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">01111111011‬</td><td style="text-align:center;">(1).1001100110011001100110011001100110011001100110011001</td><td style="text-align:center;">10011...0011...</td></tr></tbody></table><br><h3 id="舍入" tabindex="-1">舍入 <a class="header-anchor" href="#舍入" aria-hidden="true">#</a></h3><p>IEEE-754规范默认采用的舍入规则是“向最接近的值舍入”，即数字向上或向下舍入，使得舍入后的值最接近原值，如果二者精确度相同，选择偶数的结果。在二进制中，最后一位为0是偶数，1是奇数。<br><br><strong>例4-续</strong></p><p>0.1的二进制小数是无限循环的，转换为浮点数必然存在舍入操作</p><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th><th style="text-align:center;">无法表示部分</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">01111111011‬</td><td style="text-align:center;">(1).10011001100110011001100110011001100110011001100110<strong>01</strong></td><td style="text-align:center;"><strong>1001</strong>1...0011...</td></tr></tbody></table><p>为了便于描述，取fraction后2位视为整数，取无法表示部分前4位作为小数，合并记为<code>01.1001</code>，如上表中黑体部分。根据舍入规则，fraction最后2位有效数字为<code>01</code>，如果向上舍入变为<code>10</code>，向下舍入变为<code>00</code>，如何选择呢？</p><blockquote><p><code>01.1001</code>的整数部分<code>01</code>，正好是向上舍入后值<code>10</code>的一半，再加上小数部分大于<code>10</code>的一半，因此向上舍入为<code>10</code>的误差小于向下舍入为<code>00</code>的误差，所以这里选择向上舍入。</p></blockquote><p>因此，0.1<sub>10</sub>以二进制形式保存的值实际上比自身要大一点点，具体表示如下：</p><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">01111111011‬</td><td style="text-align:center;">(1).10011001100110011001100110011001100110011001100110<strong>10</strong></td></tr></tbody></table><br><p><strong>例5 将0.2转换为IEEE浮点数</strong><br> 与例4类似，转换过程如下</p><table><thead><tr><th style="text-align:center;">被乘数</th><th style="text-align:center;">积</th><th style="text-align:center;">整数</th></tr></thead><tbody><tr><td style="text-align:center;">0.2</td><td style="text-align:center;">0.4</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.4</td><td style="text-align:center;">0.8</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.8</td><td style="text-align:center;">1.6</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.6</td><td style="text-align:center;">1.2</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.2</td><td style="text-align:center;">0.4</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.4</td><td style="text-align:center;">0.8</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.8</td><td style="text-align:center;">1.6</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.6</td><td style="text-align:center;">1.2</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">0.2</td><td style="text-align:center;">0.4</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">0.4</td><td style="text-align:center;">0.8</td><td style="text-align:center;">0</td></tr></tbody></table><p>可以看到也出现了循环，因此$\\ 0.2_{10} = 0.\\overline{0011}_2=1.1\\overline{0011}_2 \\times 2^{-3}$</p><p>转换为浮点数如下：</p><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th><th style="text-align:center;">无法表示部分</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">01111111100</td><td style="text-align:center;">(1).10011001100110011001100110011001100110011001100110<strong>01</strong></td><td style="text-align:center;">10011...0011...</td></tr></tbody></table><p>按照舍入规则，最终二进制表示为</p><table><thead><tr><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">01111111100‬</td><td style="text-align:center;">(1).10011001100110011001100110011001100110011001100110<strong>10</strong></td></tr><tr><td style="text-align:center;">可以看到，它比真实的0.2也大了一点点。</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p><br><br></p><h2 id="_0-1-0-2" tabindex="-1">0.1+0.2 <a class="header-anchor" href="#_0-1-0-2" aria-hidden="true">#</a></h2><p>按照规范，两个浮点数计算时有一个步骤叫做<strong>对阶</strong>，就是让2个操作数的小数点对齐，把较小的指数转化为较大的指数，然后再按照符号进行小数部分的计算。以0.1+0.2为例：</p><blockquote><p>0.1<sub>10</sub> =1.1<strong>0011</strong><sub>2</sub>×2<sup>-4</sup><br> 0.2<sub>10</sub> = 1.1<strong>0011</strong><sub>2</sub>×2<sup>-3</sup></p></blockquote><p>计算时，要将0.1变为0.2的同阶</p><blockquote><p>0.1<sub>10</sub> =0.11<strong>0011</strong><sub>2</sub>×2<sup>-3</sup><br> 0.2<sub>10</sub> = 1.1<strong>0011</strong><sub>2</sub>×2<sup>-3</sup></p></blockquote><p>反映到二进制上就是对0.1的二进制码进行右移。因为两数的指数仅相差1，因此只需要右移1位：</p><table><thead><tr><th style="text-align:center;">0.1</th><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:left;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">移位前</td><td style="text-align:center;">0</td><td style="text-align:center;">01111111<strong>011</strong>‬</td><td style="text-align:left;">(1).1001100110011001100110011001100110011001100110011010</td></tr><tr><td style="text-align:center;">移位后</td><td style="text-align:center;">0</td><td style="text-align:center;">01111111<strong>100</strong>‬</td><td style="text-align:left;">(0).1100110011001100110011001100110011001100110011001101(0)</td></tr></tbody></table><table><thead><tr><th style="text-align:center;">0.2</th><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">不移位</td><td style="text-align:center;">0</td><td style="text-align:center;">01111111100‬</td><td style="text-align:center;">(1).1001100110011001100110011001100110011001100110011010</td></tr></tbody></table><p>相加时，指数不变，有效数部分（包括隐含的1）进行相加，变成了 $$ 0.1100110011001100110011001100110011001100110011001101\\+1.1001100110011001100110011001100110011001100110011010\\ =10.0110011001100110011001100110011001100110011001100111 $$</p><p>因为规范要求有效数的第一位为1，所以需要将和的小数点左移1位，同时指数部分加1。移位后有效数小数部分发生舍入。<br> 舍入时，最后四位是011(1)，向上舍入变成100，向下舍入变为011。原值恰好位于二者中间，无论舍入方案如何，误差都一样。在“向最接近的值舍入”失效的情况下，采用舍入后是偶数的表示形式，即向上舍入变为100。</p><table><thead><tr><th style="text-align:center;">0.1+0.2</th><th style="text-align:center;">符号位sign</th><th style="text-align:center;">指数exponent</th><th style="text-align:center;">有效数fraction</th></tr></thead><tbody><tr><td style="text-align:center;">移位前</td><td style="text-align:center;">0</td><td style="text-align:center;">01111111<strong>100</strong>‬</td><td style="text-align:center;">(10).0110011001100110011001100110011001100110011001100<strong>111</strong></td></tr><tr><td style="text-align:center;"><strong>移位后</strong></td><td style="text-align:center;">0</td><td style="text-align:center;">01111111<strong>101</strong></td><td style="text-align:center;">(1).0011001100110011001100110011001100110011001100110<strong>011</strong>(1)</td></tr><tr><td style="text-align:center;"><strong>舍入后</strong></td><td style="text-align:center;">0</td><td style="text-align:center;">01111111<strong>101</strong></td><td style="text-align:center;">(1).0011001100110011001100110011001100110011001100110<strong>100</strong></td></tr></tbody></table><p>再将二进制码转换为十进制数，于是得到<br><strong>0.1+0.2</strong> = (-1)<sup>0</sup>×2<sup>(1021-1023)</sup>×(1+1×2<sup>-3</sup>+1×2<sup>-4</sup>+1×2<sup>-7</sup>+1×2<sup>-8</sup>+1×2<sup>-11</sup>+1×2<sup>-12</sup>+1×2<sup>-15</sup>+1×2<sup>-16</sup>+1×2<sup>-19</sup>+1×2<sup>-20</sup>+1×2<sup>-23</sup>+1×2<sup>-24</sup>+1×2<sup>-27</sup>+1×2<sup>-28</sup>+1×2<sup>-31</sup>+1×2<sup>-32</sup>+1×2<sup>-35</sup>+1×2<sup>-36</sup>+1×2<sup>-39</sup>+1×2<sup>-40</sup>+1×2<sup>-43</sup>+1×2<sup>-44</sup>+1×2<sup>-47</sup>+1×2<sup>-48</sup>+1×2<sup>-50</sup>)<strong>=0.3000000000000000444089209850062616169452667236328125 ≈ 0.30000000000000004</strong></p><h3 id="题外话" tabindex="-1"> 题外话 <a class="header-anchor" href="#题外话" aria-hidden="true">#</a></h3><ul><li>为什么按照<code>符号位-&gt;指数-&gt;有效数</code>这样的顺序进行排列二进制位？ <ul><li>这样可以提高比较的速度，尽量实现一次比较得出结果：</li><li>首先比较符号位，如果正负不同，谁大谁小一目了然；</li><li>如果符号相同，那么比较指数，指数大的更大；</li><li>如果指数也相同，那么最后再比较有效数的部分；</li><li>所以才将符号位放在的最高权重位MSB上，而指数和有效数依次放在后面。</li></ul></li><li>很显然指数可正可负，这样可以分别表示大于1或小于1的数；</li><li>如果用补码表示，比较的时候又需要先比较符号位再比较数据位，规则太复杂。因此直接把11bits的指数部分当作了无符号数进行计算比较，再通过一个偏移把它映射到一个包含正负的对称区间内；</li><li>11位的二进制数可以表示2<sup>11</sup>，即2048个数，所以11位无符号数可以表示区间[0, 2047]，通过减去偏移1024或1023，可以分别映射为2个对称区间：[-1024, 1023]或[-1023,1024]。</li><li>标准中最终选择了1023作为偏移，原区间内0和2047作为特殊情况保留，得到转换后的有效指数区间[-1022,1023]。至于标准为什么要映射到对称区间，同时偏移为什么选择1023 <blockquote><p>The reason for having <code>|emin| &lt; emax</code> is so that the reciprocal of the smallest number will not overflow. Although it is true that the reciprocal of the largest number will underflow, underflow is usually less serious than overflow.</p></blockquote></li><li>因为浮点数可以有多种表示方式，比如1.1<sub>2</sub>×2<sup>5</sup>，也可以写作11<sub>2</sub>×2<sup>4</sup>，又或者0.11<sub>2</sub>×2<sup>6</sup>（因为小数点的位置可变，所以这种类型被称为浮点数）。为了规范表示，避免出现同一个数出现多种表示方法的情况，标准规定采用前者的形式，即第一位始终为1</li><li>这样隐性增加了1位，提高了精度</li></ul><hr><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-hidden="true">#</a></h2><ol><li><a href="https://floating-point-gui.de/formats/fp/" target="_blank" rel="noreferrer">https://floating-point-gui.de/formats/fp/</a></li><li><a href="https://docs.oracle.com/cd/E19957-01/806-3568/ncg_goldberg.html" target="_blank" rel="noreferrer">https://docs.oracle.com/cd/E19957-01/806-3568/ncg_goldberg.html</a></li><li><a href="https://www.cnblogs.com/bossin/archive/2007/04/08/704567.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/bossin/archive/2007/04/08/704567.html</a></li><li><a href="https://www.eecs.wsu.edu/~jdelgado/EE334/chp3b.pdf" target="_blank" rel="noreferrer">https://www.eecs.wsu.edu/~jdelgado/EE334/chp3b.pdf</a></li><li><a href="https://en.wikipedia.org/wiki/Exponent_bias" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Exponent_bias</a></li><li><a href="http://blog.reverberate.org/2014/09/what-every-computer-programmer-should.html" target="_blank" rel="noreferrer">http://blog.reverberate.org/2014/09/what-every-computer-programmer-should.html</a></li><li><a href="http://sandbox.mc.edu/~bennet/cs110/flt/dtof.html" target="_blank" rel="noreferrer">http://sandbox.mc.edu/~bennet/cs110/flt/dtof.html</a></li><li><a href="https://randomascii.wordpress.com/2012/02/25/comparing-floating-point-numbers-2012-edition/" target="_blank" rel="noreferrer">https://randomascii.wordpress.com/2012/02/25/comparing-floating-point-numbers-2012-edition/</a></li><li><a href="http://www.oxfordmathcenter.com/drupal7/node/43" target="_blank" rel="noreferrer">http://www.oxfordmathcenter.com/drupal7/node/43</a></li><li><a href="https://blog.angularindepth.com/the-mechanics-behind-exponent-bias-in-floating-point-9b3185083528" target="_blank" rel="noreferrer">https://blog.angularindepth.com/the-mechanics-behind-exponent-bias-in-floating-point-9b3185083528</a></li></ol>`,89),a=[s];function i(d,c,g,h,o,p){return e(),l("div",null,a)}const b=t(r,[["render",i]]);export{x as __pageData,b as default};
